    { id: 3, text: 'You have the power to change everything. Do you?', options: ['YES', 'NO', 'MAYBE', 'NOT YET'] },
  ];

  const handleChoice = (decisionId: number, choice: string) => {
    setChoices([...choices, choice]);
    makeChoice('sinner', choice);
  };

  return (
