'use client';

import DiamondWorld from '@/components/experience/DiamondWorld';
import { useState } from 'react';
import { motion } from 'framer-motion';

export default function SaintDiamond() {
  const [found, setFound] = useState<number[]>([]);

  const statements = [
    { id: 1, text: 'Forgiveness erases the past', true: false },
    { id: 2, text: 'Forgiveness changes what the wound means', true: true },
    { id: 3, text: 'You must forget to forgive', true: false },
    { id: 4, text: 'Forgiveness is a choice, not a feeling', true: true },
    { id: 5, text: 'Time heals all wounds automatically', true: false },
  ];

  const handleStatement = (id: number, isTrue: boolean) => {
    const statement = statements.find(s => s.id === id);
    if (statement && statement.true === isTrue && !found.includes(id)) {
      setFound([...found, id]);
    }
  };

  return (
    <DiamondWorld
      type="saint"
      title="THE SAINT"
      domain="FORGIVENESS"
      question="CAN YOU FORGIVE WHAT YOU CANNOT FORGET?"
      onComplete={() => {}}
    >
      <div className="space-y-8">
        <p className="text-gray-400 mb-8 bg-pearl-white text-void-black p-6">
          This space is different. Breathe. Discover the truths hidden among the contradictions.
        </p>

        <div className="space-y-6">
          {statements.map((statement) => (
            <motion.div
              key={statement.id}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className={`p-6 border-2 ${
                found.includes(statement.id)
                  ? 'border-deep-ruby bg-obsidian'
                  : 'border-graphite'
              }`}
            >
              <p className="text-lg mb-4">{statement.text}</p>
              <div className="flex gap-4">
                <button
                  onClick={() => handleStatement(statement.id, true)}
                  disabled={found.includes(statement.id)}
                  className="px-6 py-2 border border-graphite hover:border-deep-ruby disabled:opacity-50 transition-colors"
                >
                  TRUE
                </button>
                <button
                  onClick={() => handleStatement(statement.id, false)}
                  disabled={found.includes(statement.id)}
                  className="px-6 py-2 border border-graphite hover:border-deep-ruby disabled:opacity-50 transition-colors"
                >
                  FALSE
                </button>
              </div>
            </motion.div>
          ))}
        </div>

        {found.length === statements.filter(s => s.true).length && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="mt-12 p-8 border-2 border-deep-ruby bg-pearl-white text-void-black text-center"
          >
            <p className="text-xl mb-4">
              FORGIVENESS DOES NOT ERASE THE WOUND.
            </p>
            <p className="text-xl text-deep-ruby">
              IT CHANGES WHAT THE WOUND MEANS.
            </p>
          </motion.div>
        )}
      </div>
    </DiamondWorld>
  );
}
